using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Web.Script.Serialization;
class TaskbarPresetTests {
 static int checks,failures;static void Check(bool ok,string name){checks++;if(!ok)failures++;Console.WriteLine((ok?"PASS ":"FAIL ")+name);}
 static bool Rejected(Action action){try{action();return false;}catch(ArgumentException){return true;}}
 static int Main(string[] args){try{var runtime=new MonitorConfig{TaskbarScreen="screen-keep",TaskbarOffset=33};runtime.Quota.Enabled=false;var draft=new MonitorConfig{Appearance=TaskbarAppearance.Preset("柯南蓝"),TaskbarItems=new List<string>{"gpu","disk","codex5h"}};draft.Appearance.ItemGap=37;draft.Appearance.Items[0].Label="下载测试";runtime.TaskbarPresets=TaskbarPresets.Save(runtime,"我的方案",draft,false);Check(runtime.TaskbarPresets.Count==1,"custom preset saved");Check(runtime.Appearance.ItemGap!=37&&runtime.TaskbarItems.Count==4,"saving does not apply live appearance or items");draft.Appearance.ItemGap=59;draft.Appearance.Items[0].Label="后续改动";draft.TaskbarItems.Reverse();var loaded=TaskbarPresets.Load(runtime,"我的方案");Check(loaded.Appearance.ItemGap==37&&loaded.Appearance.Items[0].Label=="下载测试","saved appearance is a deep copy");Check(loaded.TaskbarItems.SequenceEqual(new[]{"gpu","disk","codex5h"}),"selection and item order retained");loaded.Appearance.ItemGap=88;Check(TaskbarPresets.Load(runtime,"我的方案").Appearance.ItemGap==37,"editing loaded draft cannot mutate saved preset");Check(Rejected(()=>TaskbarPresets.Save(runtime,"我的方案",draft,false)),"duplicate save rejected");Check(Rejected(()=>TaskbarPresets.Save(runtime,"柯南蓝",draft,false)),"new name cannot silently overwrite built in");Check(Rejected(()=>TaskbarPresets.Save(runtime," ",draft,false)),"empty name rejected");Check(Rejected(()=>TaskbarPresets.Save(runtime,new string('字',25),draft,false)),"overlong name rejected");
 runtime.TaskbarPresets=TaskbarPresets.Save(runtime,"柯南蓝",draft,true);Check(TaskbarPresets.Load(runtime,"柯南蓝").Appearance.ItemGap==59,"built in override can be saved");var serialized=new JavaScriptSerializer().Serialize(new AssistantConfig{Monitor=runtime});string folder=Path.Combine(args[0],"profile-roundtrip");Directory.CreateDirectory(folder);File.WriteAllText(Path.Combine(folder,"assistant.json"),serialized);var restored=new AssistantRuntime(folder);Check(TaskbarPresets.Load(restored.Config.Monitor,"柯南蓝").Appearance.ItemGap==59,"overrides survive actual runtime restart");Check(TaskbarPresets.Load(restored.Config.Monitor,"我的方案").TaskbarItems.Contains("codex5h"),"custom presets survive runtime restart");restored.Telemetry.Dispose();runtime.TaskbarPresets=TaskbarPresets.Reset(runtime,"柯南蓝");Check(TaskbarPresets.Find(runtime,"柯南蓝")==null&&TaskbarPresets.Load(runtime,"柯南蓝").Appearance.ItemGap==TaskbarAppearance.Preset("柯南蓝").ItemGap,"reset removes override and restores factory appearance");Check(TaskbarPresets.Find(runtime,"我的方案")!=null,"reset preserves other presets");Check(runtime.TaskbarScreen=="screen-keep"&&runtime.TaskbarOffset==33&&!runtime.Quota.Enabled,"preset operations leave monitor screen position and quota settings intact");Check(Rejected(()=>TaskbarPresets.Delete(runtime,"柯南蓝")),"built in cannot be deleted");runtime.TaskbarPresets=TaskbarPresets.Delete(runtime,"我的方案");Check(TaskbarPresets.Find(runtime,"我的方案")==null&&TaskbarPresets.Names(runtime).Length==5,"custom deletion retains five factory options");runtime.TaskbarPresets=null;Check(TaskbarPresets.Names(runtime).Length==5,"legacy or null preset list loads factory options");
 }catch(Exception e){failures++;Console.WriteLine(e);}Directory.CreateDirectory(args[0]);File.WriteAllText(Path.Combine(args[0],"preset-results.json"),new JavaScriptSerializer().Serialize(new{checks,failures}));return failures==0?0:1;}
}
